#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

void bfs(vector<vector<int>>& adj, int src, int n) {
    vector<int> dist(n + 1, -1);
    vector<int> parent(n + 1, -1);
    queue<int> q;

    dist[src] = 0;
    q.push(src);

    cout << "Visit order: ";
    while (!q.empty()) {
        int node = q.front(); q.pop();
        cout << node << " ";
        for (int nb : adj[node]) {
            if (dist[nb] == -1) {
                dist[nb] = dist[node] + 1;
                parent[nb] = node;
                q.push(nb);
            }
        }
    }

    cout << "\n\nNode | Level\n-----+------\n";
    for (int i = 1; i <= n; i++)
        if (dist[i] != -1)
            cout << "  " << i << "  |  " << dist[i] << "\n";

    // Path to node 12
    cout << "\nPath 1 -> 12: ";
    vector<int> path;
    for (int v = 12; v != -1; v = parent[v]) path.push_back(v);
    reverse(path.begin(), path.end());
    for (int i = 0; i < (int)path.size(); i++) {
        cout << path[i];
        if (i + 1 < (int)path.size()) cout << " -> ";
    }
    cout << "  (distance = " << dist[12] << ")\n";
}

int main() {
    int n = 12;
    vector<vector<int>> adj(n + 1);
    auto add = [&](int u, int v) {
        adj[u].push_back(v); adj[v].push_back(u);
    };
    add(1,2); add(1,3); add(1,4);
    add(2,5); add(2,6); add(3,7);
    add(4,8); add(4,9);
    add(5,10); add(5,11); add(7,12);

    bfs(adj, 1, n);
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <climits>
