#include <numeric>
using namespace std;

typedef pair<int,int> pii;

// Graph: A-H (0-7), Source=A(0), Target=H(7) (same as image)
void dijkstra(vector<vector<pii>>& adj, int src, int n) {
    vector<int>  dist(n, INT_MAX);
    vector<int>  parent(n, -1);
    vector<bool> settled(n, false);
    priority_queue<pii, vector<pii>, greater<pii>> pq;  // min-heap

    dist[src] = 0;
    pq.push({0, src});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (settled[u]) continue;
        settled[u] = true;

        for (auto [w, v] : adj[u]) {
            if (dist[u] + w < dist[v]) {   // relaxation
                dist[v]   = dist[u] + w;
                parent[v] = u;
                pq.push({dist[v], v});
            }
        }
    }

    string names = "ABCDEFGH";
    cout << "Node | Distance from A\n-----+----------------\n";
    for (int i = 0; i < n; i++)
        cout << "  " << names[i] << "  |  "
             << (dist[i] == INT_MAX ? -1 : dist[i]) << "\n";

    // Print path A -> H
    cout << "\nShortest path A -> H: ";
    vector<int> path;
    for (int v = 7; v != -1; v = parent[v]) path.push_back(v);
    reverse(path.begin(), path.end());
    for (int i = 0; i < path.size(); i++) {
        cout << names[path[i]];
        if (i + 1 < path.size()) cout << " -> ";
    }
    cout << "  (cost = " << dist[7] << ")\n";
}

int main() {
    int n = 8;  // A B C D E F G H
    vector<vector<pii>> adj(n);

    auto addEdge = [&](int u, int v, int w) {
        adj[u].push_back({w, v});
        adj[v].push_back({w, u});
    };

    addEdge(0,1,4); addEdge(0,2,2); addEdge(1,3,3);
    addEdge(1,4,1); addEdge(2,4,5); addEdge(2,5,6);
    addEdge(3,6,2); addEdge(4,6,3); addEdge(4,7,4);
    addEdge(5,7,2); addEdge(6,7,1);

    dijkstra(adj, 0, n);
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

const int INF = 1e8;

// Graph: A-E (0-4), directed weighted (same as image)
void floydWarshall(int n, vector<vector<int>>& dist,
                   vector<vector<int>>& next) {
    for (int k = 0; k < n; k++)           // intermediate node
        for (int i = 0; i < n; i++)        // source
            for (int j = 0; j < n; j++)    // destination
                if (dist[i][k] < INF && dist[k][j] < INF)
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                        next[i][j] = next[i][k];
                    }
}

vector<int> getPath(int u, int v, vector<vector<int>>& next) {
    if (next[u][v] == -1) return {};
    vector<int> path = {u};
    while (u != v) { u = next[u][v]; path.push_back(u); }
    return path;
}

int main() {
    int n = 5;
    string names = "ABCDE";

    vector<vector<int>> dist(n, vector<int>(n, INF));
    vector<vector<int>> next(n, vector<int>(n, -1));

    for (int i = 0; i < n; i++) { dist[i][i] = 0; next[i][i] = i; }

    auto addEdge = [&](int u, int v, int w) {
        dist[u][v] = w;
        next[u][v] = v;
    };

    addEdge(0,1,3); addEdge(0,4,7);
    addEdge(1,2,2); addEdge(1,3,6);
    addEdge(2,3,1); addEdge(3,4,2);
    addEdge(4,1,4); addEdge(4,2,8);

    floydWarshall(n, dist, next);

    // Print distance matrix
    cout << "All-Pairs Shortest Distance Matrix:\n\n     ";
    for (int j = 0; j < n; j++) cout << names[j] << "   ";
    cout << "\n    +" << string(n*4, '-') << "\n";
    for (int i = 0; i < n; i++) {
        cout << " " << names[i] << "  |";
        for (int j = 0; j < n; j++)
            cout << (dist[i][j] == INF ? "  INF" : "  " + to_string(dist[i][j]) + " ");
        cout << "\n";
    }

    // Print path A -> C
    cout << "\nPath A -> C: ";
    auto path = getPath(0, 2, next);
    for (int i = 0; i < path.size(); i++) {
        cout << names[path[i]];
        if (i + 1 < path.size()) cout << " -> ";
    }
    cout << "  (cost = " << dist[0][2] << ")\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <climits>
#include <algorithm>
using namespace std;

struct Edge { int u, v, w; };

void bellmanFord(int n, int src, vector<Edge>& edges) {
    vector<int> dist(n, INT_MAX);
    vector<int> parent(n, -1);
    dist[src] = 0;

    // N-1 relaxation rounds
    for (int round = 1; round <= n - 1; round++) {
        bool updated = false;
        for (auto& e : edges) {
            if (dist[e.u] != INT_MAX &&
                dist[e.u] + e.w < dist[e.v]) {
                dist[e.v]    = dist[e.u] + e.w;
                parent[e.v]  = e.u;
                updated      = true;
            }
        }
        if (!updated) {
            cout << "Converged early at round " << round << "\n";
            break;
        }
    }

    // Check for negative cycle (round N)
    bool negCycle = false;
    for (auto& e : edges) {
        if (dist[e.u] != INT_MAX &&
            dist[e.u] + e.w < dist[e.v]) {
            negCycle = true;
            break;
        }
    }

    string names = "SABTCD";   // 0=S 1=A 2=B 3=C 4=D 5=T
    // reorder to match image: S A B C D T
    string nm = "SABCDT";

    cout << (negCycle ? "NEGATIVE CYCLE DETECTED!\n" : "No negative cycle.\n");
    cout << "\nNode | Distance from S\n-----+----------------\n";
    for (int i = 0; i < n; i++)
        cout << "  " << nm[i] << "  |  "
             << (dist[i] == INT_MAX ? -1 : dist[i]) << "\n";

    // Path S -> T (index 5)
    cout << "\nShortest path S -> T: ";
    vector<int> path;
    for (int v = 5; v != -1; v = parent[v]) path.push_back(v);
    reverse(path.begin(), path.end());
    for (int i = 0; i < (int)path.size(); i++) {
        cout << nm[path[i]];
        if (i+1 < (int)path.size()) cout << " -> ";
    }
    cout << "  (cost = " << dist[5] << ")\n";
}

int main() {
    // S=0 A=1 B=2 C=3 D=4 T=5
    int n = 6;
    vector<Edge> edges = {
        {0,1, 6},   // S->A
        {0,2, 7},   // S->B
        {1,3, 5},   // A->C
        {1,4,-4},   // A->D  (NEGATIVE)
        {2,1, 8},   // B->A
        {2,4, 9},   // B->D
        {2,3,-3},   // B->C  (NEGATIVE)
        {3,5, 7},   // C->T
        {4,5,15},   // D->T
        {4,3, 7},   // D->C
    };

    bellmanFord(n, 0, edges);
    return 0;
}
